import re

from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class UecStats(GenericEPCSIMCommand):
    """Command uec_stats."""

    def __init__(self, connection, cmd_type=None, enb=None, cell=None, prompt=None, newline_chars=None, runner=None):
        """
        Command uec_stats.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(UecStats, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.cmd_type = cmd_type
        self.enb = enb
        self.cell = cell
        self.current_ret["Counter"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"uec_stats type={self.cmd_type} enb={self.enb} cell={self.cell}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_uec_stats_success_rate(line)
                self._parse_uec_stats_counter(line)
            except ParsingDone:
                pass
        return super(UecStats, self).on_new_line(line, is_full_line)

    # Global Success Rate (%)               100.00
    _re_uec_stats_success_rate = re.compile(r"(?P<COUNTER>^(.+%.*?(?=  )))+\s+(?P<VALUE>\d+.?\d*)")

    def _parse_uec_stats_success_rate(self, line):
        if self._regex_helper.search_compiled(UecStats._re_uec_stats_success_rate, line):
            self.current_ret[self._regex_helper.group("COUNTER")] = convert_to_number(self._regex_helper.group("VALUE"))
            raise ParsingDone

    # Attach                                98
    _re_uec_stats_counter = re.compile(r"(?P<COUNTER>^(.+?(?=  )))+\s+(?P<VALUE>\d+.?\d*)")

    def _parse_uec_stats_counter(self, line):
        if self._regex_helper.search_compiled(UecStats._re_uec_stats_counter, line):
            self.current_ret["Counter"][self._regex_helper.group("COUNTER")] = convert_to_number(self._regex_helper.group("VALUE"))
            raise ParsingDone


